INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q3536834', 'Treaty of Melfi', 'The Treaty of Melfi or Concordat of Melfi was signed on 23 August 1059 between Pope Nicholas II and the Norman princes Robert Guiscard and Richard I of Capua. Based on the terms of the accord, the Pope recognized the Norman conquest of Southern Italy.', 1059, 8, 23, NULL, NULL, NULL, 'day', '23 August 1059', 39, 'https://en.wikipedia.org/wiki/Treaty_of_Melfi'),
  ('Q1172638', 'Treaty of Mignano', 'The Treaty of Mignano of 1139 was the treaty which ended more than a decade of constant war in the Italian Mezzogiorno following the union of the mainland duchy of Apulia and Calabria with the County of Sicily in 1127. In 1130, Antipope Anacletus II had crowned Roger II king.', 1139, 7, 25, NULL, NULL, NULL, 'day', '25 July 1139', 34, 'https://en.wikipedia.org/wiki/Treaty_of_Mignano'),
  ('Q7837023', 'Treaty of Constance', 'The First Treaty of Constance was signed between the Emperor Frederick I and Pope Eugene III in 1153. By the terms of the treaty, the Emperor was to prevent any action by Manuel I Komnenos to reestablish the Byzantine Empire on Italian soil and to assist the pope against his enemies in revolt in Rome.', 1153, 3, 23, NULL, NULL, NULL, 'day', '23 March 1153', 39, 'https://en.wikipedia.org/wiki/Treaty_of_Constance_(1153)'),
  ('Q1566410', 'Treaty of Benevento', 'The Treaty of Benevento or Concordat of Benevento (18 June 1156) was an important treaty between the papacy of Adrian IV and the Norman Kingdom of Sicily. After years of turbulent relations, the popes finally settled down to a peace with the Hauteville kings.', 1156, 6, 18, NULL, NULL, NULL, 'day', '18 June 1156', 39, 'https://en.wikipedia.org/wiki/Treaty_of_Benevento'),
  ('Q788050', 'Treaty of Venice', 'The Treaty or Peace of Venice, 1177, was a peace treaty between the papacy and its allies, the north Italian city-states of the Lombard League, and Frederick I ”Barbarossa,” Holy Roman Emperor. The Norman Kingdom of Sicily also took part in negotiations and the treaty thereby determined the political course of all Italy for the next several years.', 1177, NULL, NULL, NULL, NULL, NULL, 'year', '1177', 57, 'https://en.wikipedia.org/wiki/Treaty_of_Venice'),
  ('Q675857', 'Treaty of Speyer', 'The Treaty of Speyer was signed in 1209 by Holy Roman Emperor Otto IV. This agreement was developed as a result of Pope Innocent III having launched an appeal for organizing a crusade against the Cathars (or Albigensians) in southern France. The accord allowed Emperor Otto IV to renounce the Concordat of Worms and claim authority over territories controlled by the Pope.', 1209, NULL, NULL, NULL, NULL, NULL, 'year', '1209', 34, 'https://en.wikipedia.org/wiki/Treaty_of_Speyer_(1209)'),
  ('Q1748198', 'Treaty of San Germano', 'The Treaty of San Germano was signed on 23 July 1230 at San Germano, present-day Cassino, ending the War of the Keys that had begun in 1228. The parties were Pope Gregory IX and Frederick II, king of Sicily and Holy Roman emperor.', 1230, 7, 20, NULL, NULL, NULL, 'day', '20 July 1230', 41, 'https://en.wikipedia.org/wiki/Treaty_of_San_Germano'),
  ('Q3997892', 'Treaty of Ceprano', 'The Treaty of San Germano was signed on 23 July 1230 at San Germano, present-day Cassino, ending the War of the Keys that had begun in 1228. The parties were Pope Gregory IX and Frederick II, king of Sicily and Holy Roman emperor.', 1230, 8, NULL, NULL, NULL, NULL, 'month', 'August 1230', 34, 'https://en.wikipedia.org/wiki/Treaty_of_Ceprano_(1230)'),
  ('Q1456414', 'Treaty of Anagni', 'The Treaty of Anagni was an accord between the Pope Boniface VIII, James II of Aragon, Philip IV of France, Charles II of Naples, and James II of Majorca. It was signed on 20 June 1295 at Anagni, in central Italy.', 1295, 6, 24, NULL, NULL, NULL, 'day', '24 June 1295', 47, 'https://en.wikipedia.org/wiki/Treaty_of_Anagni'),
  ('Q2600616', 'Treaty of London', 'The Treaty of London (Dutch: Verdrag van Londen, French: Traités de Londres, Italian: Trattato di Londra, Spanish: Tratado de Londres) in 1518 was a non-aggression pact between the major European states. The signatories were France, England, the Holy Roman Empire, the Netherlands, the Papal States and Spain, all of whom agreed not to attack one another and to come to the aid of any that were under attack.', 1518, NULL, NULL, NULL, NULL, NULL, 'year', '1518', 50, 'https://en.wikipedia.org/wiki/Treaty_of_London_(1518)'),
  ('Q684311', 'Paris Declaration Respecting Maritime Law', 'The Paris Declaration Respecting Maritime Law of 16 April 1856 was an international multilateral treaty agreed to by the warring parties in the Crimean War gathered at the Congress at Paris after the peace treaty of Paris had been signed in March 1856. As an important juridical novelty in international law, the treaty for the first time created the possibility for nations that were not involved in the establishment of the agreement and did not sign, to become a party by acceding the declaration afterwards.', 1856, 4, 16, NULL, NULL, NULL, 'day', '16 April 1856', 57, 'https://en.wikipedia.org/wiki/Paris_Declaration_Respecting_Maritime_Law'),
  ('Q2909620', 'Bombing of the Vatican', 'Rome, along with Vatican City, was bombed several times during 1943 and 1944, primarily by Allied and to a smaller degree by Axis aircraft, before the city was liberated by the Allies on June 4, 1944. Pope Pius XII was initially unsuccessful in attempting to have Rome declared an open city, through negotiations with U.S. President Franklin D. Roosevelt via Archbishop (later Cardinal) Francis Spellman.', 1943, 11, 5, NULL, NULL, NULL, 'day', '5 November 1943', 39, 'https://en.wikipedia.org/wiki/Bombing_of_the_Vatican'),
  ('Q973748', 'Fourth Geneva Convention', 'The Geneva Convention (IV) relative to the Protection of Civilian Persons in Time of War (French: Convention relative à la protection des personnes civiles en temps de guerre), more commonly referred to as the Fourth Geneva Convention or Geneva Convention IV (abbreviated as GCIV), is one of the four treaties of the 1949 Geneva Conventions. It was adopted on 12 August 1949, and came into force in October 1950.', 1949, 8, 12, NULL, NULL, NULL, 'day', '12 August 1949', 71, 'https://en.wikipedia.org/wiki/Fourth_Geneva_Convention'),
  ('Q3984882', 'Third Geneva Convention', 'The Geneva Convention (III) relative to the Treatment of Prisoners of War, more commonly referred to as the Third Geneva Convention or Geneva Convention III and abbreviated as GCIII, is one of the four treaties of the 1949 Geneva Conventions. It was first adopted in 1929, but was significantly revised at the 1949 conference on 12 August 1949.', 1949, 8, 12, NULL, NULL, NULL, 'day', '12 August 1949', 63, 'https://en.wikipedia.org/wiki/Third_Geneva_Convention'),
  ('Q186444', 'Treaty on the Non-Proliferation of Nuclear Weapons', 'The Treaty on the Non-Proliferation of Nuclear Weapons, commonly known as the Non-Proliferation Treaty or NPT, is an international treaty, the objective of which is to prevent the spread of nuclear weapons and weapons technology, to promote cooperation in the peaceful uses of nuclear energy, and to further the goal of achieving nuclear disarmament and general and complete disarmament. Between 1965 and 1968, the treaty was negotiated by the Eighteen Nation Committee on Disarmament, a United Nations-sponsored organization based in Geneva, Switzerland.', 1968, 7, 1, NULL, NULL, NULL, 'day', '1 July 1968', 83, 'https://en.wikipedia.org/wiki/Treaty_on_the_Non-Proliferation_of_Nuclear_Weapons'),
  ('Q2401715', 'Protocol II', 'Protocol II (also Additional Protocol II or AP II) is a 1977 amendment or optional protocol to the Geneva Conventions of 1949 relating to the protection of victims of non-international armed conflicts. It defines certain international laws that strive to provide better protection for victims of internal armed conflicts that take place within the borders of a single country.', 1977, NULL, NULL, NULL, NULL, NULL, 'year', '1977', 56, 'https://en.wikipedia.org/wiki/Protocol_II_to_the_Geneva_Conventions'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe');
